"""Prompt registry for code generated by protoc-gen-mcp."""

from __future__ import annotations

import weakref
from dataclasses import dataclass
from typing import Any

import mcp.server.lowlevel
import mcp.shared.exceptions
import mcp.types

from ._tools import normalize_tool_segment
from ._util import maybe_await


@dataclass(frozen=True)
class RegisteredPrompt:
    prompt: mcp.types.Prompt
    required: tuple[str, ...]
    handler: Any


class PromptRegistry:
    """Prompts registered on one low-level server, shared by every generated module."""

    def __init__(self) -> None:
        self.prompts: dict[str, RegisteredPrompt] = {}

    def add(self, prompt: RegisteredPrompt) -> None:
        if prompt.prompt.name in self.prompts:
            raise ValueError(f"duplicate prompt registration: {prompt.prompt.name}")
        self.prompts[prompt.prompt.name] = prompt


_REGISTRIES: weakref.WeakKeyDictionary[mcp.server.lowlevel.Server, PromptRegistry] = weakref.WeakKeyDictionary()


def prompt_name(namespace: str | None, name: str) -> str:
    if namespace is None or normalize_tool_segment(namespace) == "":
        return normalize_tool_segment(name)
    return f"{normalize_tool_segment(namespace)}_{normalize_tool_segment(name)}"


def _prompt_error(message: str) -> mcp.shared.exceptions.McpError:
    return mcp.shared.exceptions.McpError(mcp.types.ErrorData(code=mcp.types.INVALID_PARAMS, message=message))


def install_prompt_registry(server: mcp.server.lowlevel.Server) -> PromptRegistry:
    """Returns the server's prompt registry, installing the SDK prompt handlers once."""
    registry = _REGISTRIES.get(server)
    if registry is not None:
        return registry
    registry = PromptRegistry()
    _REGISTRIES[server] = registry

    @server.list_prompts()
    async def _list_prompts() -> list[mcp.types.Prompt]:
        return [entry.prompt for entry in registry.prompts.values()]

    @server.get_prompt()
    async def _get_prompt(name: str, arguments: dict[str, str] | None) -> mcp.types.GetPromptResult:
        entry = registry.prompts.get(name)
        if entry is None:
            raise _prompt_error(f"unknown prompt {name!r}")
        args = dict(arguments or {})
        for required in entry.required:
            if required not in args:
                raise _prompt_error(f"missing required prompt argument: {required}")
        return await maybe_await(entry.handler(args))

    return registry
